"""One-off curation. Source objects are immutable; the generated TS is static."""
import json
from pathlib import Path
objects = {o['metId']: o for o in json.loads(Path('data/met-objects.json').read_text())}
def L(fr, en, ja): return dict(fr=fr,en=en,ja=ja)
entries=[]
def add(met, sale, low, high, kind, title, date, medium, intro, attribution=None, death=None):
    o=objects[met]
    entries.append(dict(met=met,sale=sale,low=low,high=high,kind=kind,title=title,date=date,medium=medium,intro=intro,attribution=attribution,death=death))
