continuations={
'print':L('Le travail de la ligne et des aplats de couleur relève de l’impression sur bois. Ce témoignage de la culture de l’estampe se prête à une lecture attentive, de près.', 'The interplay of line and colour reflects the woodblock printing process. This example of print culture rewards close viewing.', '線と色面の関係に木版印刷の技法がうかがえる。近くで細部を見ることで、版画表現の豊かさを味わえる。'),
'ceramic':L('Le façonnage et la cuisson déterminent ensemble le caractère de la surface. L’objet témoigne d’un équilibre entre fonction, forme et décor.', 'Forming and firing together determine the character of the surface. The object balances function, shape and decoration.', '成形と焼成が一体となり、表面の表情を生んでいる。用途、器形、装飾の関係を伝える一品。'),
'wood':L('Sa fonction était de retenir à la ceinture un accessoire suspendu. La sculpture doit être appréciée sous plusieurs angles, à l’échelle de la main.', 'Its function was to secure a suspended accessory at the sash. The carving is intended to be viewed from several angles, at the scale of the hand.', '帯から下げる提物の留め具として使われた。手の中でさまざまな角度から見ることを前提とした彫刻である。'),
'lacquer':L('Les différentes matières créent un jeu de reflets à petite échelle. La qualité du décor s’apprécie dans le rapport entre la surface et le volume.', 'The materials create shifting reflections on an intimate scale. The decoration is best appreciated in the relationship between surface and volume.', '小さな器面に素材の異なる光沢が生まれている。表面の装飾と立体の関係に見どころがある。'),
'metal':L('La fonte ou le travail du métal donne à la surface son relief et sa densité. Les variations de patine contribuent à la lecture du volume.', 'Casting or metalworking gives the surface its relief and density. Variations in patina contribute to the reading of the volume.', '鋳造や金属加工による起伏と質感を備えている。古色の変化が立体の見え方に深みを与える。'),
'jade':L('La taille et le polissage mettent en valeur la densité de la pierre. L’objet associe la culture de l’écrit à un travail lapidaire de précision.', 'Carving and polishing reveal the density of the stone. The object brings the culture of writing together with precise lapidary work.', '彫刻と研磨によって石の緻密さを引き出している。書の文化と精緻な玉彫を結び付けた作品。'),
'paper':L('L’encre et l’or hiérarchisent l’espace de la page. La composition se lit autant comme un document que comme un travail graphique.', 'Ink and gold establish a hierarchy across the page. The composition may be read both as a document and as a graphic work.', '墨と金が紙面に秩序を与えている。資料として、また書の造形として鑑賞できる。'),
'photo':L('Le procédé à l’albumine produit une image aux nuances fines, caractéristique du XIXe siècle. Le tirage invite à observer le cadrage et les détails du Japon de cette époque.', 'The albumen process produces the fine tonal range characteristic of 19th-century photographs. The print invites attention to framing and to details of Japan at the time.', '鶏卵紙の技法による、19世紀写真特有の細やかな階調を備える。構図と当時の日本の細部を読み取る楽しみがある。'),
'ambrotype':L('L’image est formée sur une plaque de verre selon le procédé de l’ambrotype. L’étui participe à la présentation et à la conservation de ce portrait unique.', 'The image is formed on a glass plate through the ambrotype process. Its case contributes to the presentation and preservation of this unique portrait.', 'ガラス板に像を形成するアンブロタイプの技法による。ケースは一点物の肖像の展示と保存を兼ねている。'),
'screen':L('Le pli des panneaux permet de moduler l’espace et la perception de l’image. L’œuvre associe ainsi une fonction d’ameublement à une composition picturale.', 'The fold between the panels modulates space and the perception of the image. The work combines the function of a furnishing with a pictorial composition.', '折れによって空間と画面の見え方を調節できる。調度としての役割と絵画表現を兼ね備えている。'),
'textile':L('Le tombé et la texture du tissu participent pleinement à sa lecture. Le vêtement offre un regard sur la rencontre entre technique textile et usage.', 'The drape and texture of the fabric are integral to its character. The garment offers a view of the relationship between textile technique and use.', '生地の落ち方と質感も作品の表情を形づくる。織物の技法と用途との関係をうかがわせる衣服。')}
conditions={
'print':L('Légères rousseurs et patine du papier. Petites marques en marge. Couleurs conservant une bonne lisibilité ; rapport illustratif.', 'Light foxing and paper toning. Small marks at the margins. Colours remain legible; illustrative report.', '軽い点状の染みと紙の変色。余白に小さな擦れ。色彩の判読性は良好。デモ用の状態記述。'),
'ceramic':L('Usure légère de la couverte. Frottements au talon compatibles avec l’usage. Petite irrégularité de cuisson ; rapport illustratif.', 'Light glaze wear. Rubbing at the foot consistent with use. A small firing irregularity; illustrative report.', '釉面に軽い擦れ。高台に使用に伴う摩耗。小さな焼成上の不整。デモ用の状態記述。'),
'wood':L('Patine d’usage et légers frottements. Petites marques de manipulation. Sculpture lisible ; rapport illustratif.', 'Handling patina and light rubbing. Small handling marks. Carving remains legible; illustrative report.', '使用に伴う古色と軽い擦れ。小さな取り扱い痕。彫刻は明瞭。デモ用の状態記述。'),
'lacquer':L('Micro-rayures sur la laque. Légère usure des rehauts métalliques. Petits frottements aux angles ; rapport illustratif.', 'Fine scratches to the lacquer. Light wear to metallic decoration. Small rubbed areas at the corners; illustrative report.', '漆面に細かな擦り傷。金属装飾に軽い摩耗。角に小さな擦れ。デモ用の状態記述。'),
'metal':L('Patine de surface irrégulière. Légères marques de manipulation. Petites usures des reliefs ; rapport illustratif.', 'Uneven surface patina. Light handling marks. Minor wear to raised areas; illustrative report.', '表面の古色に変化。軽い取り扱い痕。突出部に小さな摩耗。デモ用の状態記述。'),
'jade':L('Légères marques de surface. Inclusions et nuances naturelles de la pierre. Petits frottements aux bords ; rapport illustratif.', 'Light surface marks. Natural inclusions and variations in the stone. Minor edge rubbing; illustrative report.', '表面に軽い痕跡。石の天然の内包物と色調の変化。縁に小さな擦れ。デモ用の状態記述。'),
'paper':L('Papier légèrement patiné. Marques de plis et petites rousseurs. Écriture lisible ; rapport illustratif.', 'Lightly toned paper. Fold marks and small spots of foxing. Writing remains legible; illustrative report.', '紙に軽い変色。折れ跡と小さな染み。文字は判読可能。デモ用の状態記述。'),
'photo':L('Légère patine du tirage. Petites marques aux bords. Nuances encore lisibles ; rapport illustratif.', 'Light print toning. Small marks at the edges. Tonal detail remains legible; illustrative report.', '印画に軽い変色。縁に小さな痕跡。階調の細部は判読可能。デモ用の状態記述。'),
'ambrotype':L('Légères traces sur le verre. Usure d’usage de l’étui. Image lisible ; rapport illustratif.', 'Light marks on the glass. Handling wear to the case. Image remains legible; illustrative report.', 'ガラスに軽い痕跡。ケースに使用に伴う摩耗。画像は判読可能。デモ用の状態記述。'),
'screen':L('Légère usure des plis. Petits frottements au fond d’or. Marques ponctuelles sur le papier ; rapport illustratif.', 'Light wear at the folds. Small rubbed areas to the gold. Localised paper marks; illustrative report.', '折れに軽い摩耗。金地に小さな擦れ。紙面に点状の痕跡。デモ用の状態記述。'),
'textile':L('Légers plis de conservation. Petits frottements du tissu. Quelques fils tirés ; rapport illustratif.', 'Light storage creases. Minor rubbing to the fabric. A few pulled threads; illustrative report.', '保管による軽い折れ。生地に小さな擦れ。一部に糸の引きつれ。デモ用の状態記述。')}
provenances=[L('Collection particulière, Lyon, acquis dans les années 1980 (illustratif).','Private collection, Lyon, acquired in the 1980s (illustrative).','リヨンの個人蔵、1980年代に取得（デモ用）。'),L('Collection particulière, Paris, acquis dans les années 1990 (illustratif).','Private collection, Paris, acquired in the 1990s (illustrative).','パリの個人蔵、1990年代に取得（デモ用）。'),L('Collection particulière européenne, par descendance (illustratif).','European private collection, by descent (illustrative).','ヨーロッパの個人蔵、相続による（デモ用）。')]
result=[]
indices={}
for k,e in enumerate(entries):
 o=objects[e['met']]; sale=e['sale']; i=indices.get(sale,0); indices[sale]=i+1
 attribution=e['attribution'] or L('Japon, époque Edo' if sale=='A' else 'Japon, XVIIIe siècle' if e['met']==55974 else 'Japon, ère Meiji', 'Japan, Edo period' if sale=='A' else 'Japan, 18th century' if e['met']==55974 else 'Japan, Meiji period','日本、江戸時代' if sale=='A' else '日本、18世紀' if e['met']==55974 else '日本、明治時代')
 shipping=(18,35,65) if e['kind'] in ['print','paper','photo','ambrotype','wood'] else (35,65,120) if e['kind'] in ['ceramic','lacquer','jade','metal'] else (65,120,220)
 result.append(dict(id=f'{sale}-{i+1:03}',saleId=sale,index=i,metId=o['metId'],image=o['image'],title=e['title'],attribution=attribution,description={lang:e['intro'][lang]+' '+continuations[e['kind']][lang] for lang in ['fr','en','ja']},condition=conditions[e['kind']],provenance=provenances[k%len(provenances)],medium=e['medium'],date=e['date'],dimensions=o['dimensions'] or '—',artistDeathYear=e['death'],estimateLow=e['low'],estimateHigh=e['high'],sellerType='pro' if k%3==0 else 'private',shipping=dict(zip(['france','eu','world'],shipping)),objectURL=o['objectURL'],creditLine=o['creditLine']))
sales=[
dict(id='A',title=L('Art japonais : d’Edo à Meiji','Japanese Art: Edo to Meiji','日本美術：江戸から明治'),intro=L('L’estampe, la céramique et les arts du petit objet composent ce regard sur le Japon d’Edo à Meiji. Les paysages de Hiroshige et de Hokusai dialoguent avec les surfaces des porcelaines et des laques. Chaque pièce invite à observer le lien entre technique et usage. Les estimations et les états sont proposés à titre illustratif.', 'Prints, ceramics and small objects shape this view of Japan from Edo to Meiji. Landscapes by Hiroshige and Hokusai enter into dialogue with porcelain and lacquer surfaces. Each piece invites attention to the relationship between technique and use. Estimates and condition reports are illustrative.', '版画、陶磁器、小さな工芸品を通して、江戸から明治の日本を紹介します。広重や北斎の風景に、磁器や漆の表情を取り合わせました。技法と用途の関係に目を向けてご覧ください。見積と状態報告はデモ用の設定です。'),offsetDays=2),
dict(id='B',title=L('Art asiatique : Chine, Corée et au-delà','Asian Art: China, Korea and Beyond','アジア美術：中国・朝鮮とその周辺'),intro=L('La circulation des formes et des savoir-faire guide cette sélection asiatique. Le céladon de Goryeo côtoie les porcelaines chinoises, le jade et les arts de l’écrit. Des œuvres d’Iznik et d’Asie du Sud-Est élargissent ce parcours. Le catalogue privilégie des attributions mesurées et des descriptions précises.', 'The movement of forms and techniques guides this Asian selection. Goryeo celadon sits alongside Chinese porcelain, jade and the arts of writing. Works from Iznik and Southeast Asia extend the journey. The catalogue favours measured attributions and precise descriptions.', '造形と技法の交流を軸に、アジアの作品を選びました。高麗青磁、中国磁器、玉器、書の文化を紹介します。イズニクや東南アジアの作品が視野を広げます。帰属を慎重に示し、明瞭な記述を心がけたカタログです。'),offsetDays=5),
dict(id='C',title=L('Les débuts de la photographie au Japon','Early Photography of Japan','日本の初期写真'),intro=L('Portraits et vues de lieux composent un regard sur le Japon de la seconde moitié du XIXe siècle. Les tirages à l’albumine témoignent de la diffusion rapide d’un nouveau médium. Un ambrotype rappelle la dimension intime du portrait photographique. Toutes les images retenues représentent le Japon ou ses habitants.', 'Portraits and views form a picture of Japan in the second half of the 19th century. Albumen prints trace the rapid spread of a new medium. An ambrotype recalls the intimate scale of the photographic portrait. All selected images depict Japan or its people.', '19世紀後半の日本を、肖像と風景写真からたどります。鶏卵紙の作品は、新しい表現媒体の急速な広がりを伝えます。アンブロタイプからは写真肖像の親密な性格がうかがえます。日本または日本の人々を写した作品を選んでいます。'),offsetDays=7),
dict(id='D',title=L('Design et objets','Design & Objects','デザインと工芸品'),intro=L('Boîtes, vêtements et objets décoratifs partagent ici une attention à la matière. Les laques japonaises rencontrent le japonisme britannique et les textiles de l’ère Meiji. Un paravent rappelle le rôle des images dans l’aménagement de l’espace. La sélection explore les frontières souples entre beaux-arts, arts décoratifs et usage quotidien.', 'Boxes, garments and decorative objects share an attention to materials. Japanese lacquer meets British Japonisme and Meiji-period textiles. A folding screen recalls the role of images in shaping an interior. The selection explores the fluid boundaries between art, decoration and daily use.', '箱、衣服、装飾品を、素材へのまなざしで結びました。日本の漆工に、英国のジャポニスムと明治の染織を取り合わせています。屏風は、空間を形づくる絵画の役割を示します。美術、装飾、日々の用途の間にある緩やかな関係を紹介します。'),offsetDays=9)
]
header='''// Curated from data/met-objects.json. Museum objects are CC0; market details are illustrative.\nexport type Lang = 'fr' | 'en' | 'ja';\nexport type Localized = Record<Lang, string>;\nexport type SaleId = 'A' | 'B' | 'C' | 'D';\nexport interface Sale { id: SaleId; title: Localized; intro: Localized; offsetDays: number }\nexport interface Lot {\n  id: string; saleId: SaleId; index: number; metId: number; image: string;\n  title: Localized; attribution: Localized; description: Localized; condition: Localized;\n  provenance: Localized; medium: Localized; date: Localized; dimensions: string;\n  artistDeathYear: number | null; estimateLow: number; estimateHigh: number;\n  sellerType: 'private' | 'pro'; shipping: { france: number; eu: number; world: number };\n  objectURL: string; creditLine: string;\n}\n\n'''
Path('src/data/lots.ts').write_text(header+'export const sales: Sale[] = '+json.dumps(sales,ensure_ascii=False,indent=2)+';\n\nexport const lots: Lot[] = '+json.dumps(result,ensure_ascii=False,indent=2)+';\n\nexport const findLot = (id: string | undefined): Lot | undefined => lots.find(lot => lot.id === id);\n')
print(f'Wrote {len(result)} lots: {indices}')
